package com.crms.controller;import com.crms.entity.Interview;import com.crms.repository.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import java.util.*;@RestController @RequestMapping("/api/interviews") public class InterviewController{private final InterviewRepository interviews;private final UserRepository users;public InterviewController(InterviewRepository i,UserRepository u){interviews=i;users=u;}@GetMapping("/my")public List<Interview> mine(Authentication a){return interviews.findByApplicationStudentUserId(users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId());}@PostMapping public Interview create(@RequestBody Interview i){return interviews.save(i);}@PutMapping("/{id}")public Interview update(@PathVariable Long id,@RequestBody Interview in){var x=interviews.findById(id).orElseThrow();x.setScheduledAt(in.getScheduledAt());x.setMode(in.getMode());x.setMeetingLink(in.getMeetingLink());x.setStatus(in.getStatus());x.setFeedback(in.getFeedback());return interviews.save(x);}}
